class DSparkProposer:
    """GQA DSpark speculative decoding proposer."""

    @staticmethod
    def _resolve_kernel_block_size(
        gid: int,
        kv_cache_spec,
        kernel_block_sizes: list[int] | None,
    ) -> int:
        """Return the logical block size used by the expanded block table.

        The runner now passes one normalized kernel block size per KV-cache
        group, so we select the value directly by gid instead of probing
        runner.input_batch.block_table with try-catch.
        """
        if kernel_block_sizes is not None and gid < len(kernel_block_sizes):
            return int(kernel_block_sizes[gid])
        return int(kv_cache_spec.block_size)

